{
  "headline": "FDA lists ifosfamide injection as a current shortage first posted 2026-06-12 with no public signal at our plants",
  "headline_cites": ["E12", "E8", "E9", "E10", "E11"],
  "sentences": [
    {
      "text": "FDA's shortage list shows ifosfamide injection as Current with an initial posting date of 2026-06-12 and updates through 2026-10-16.",
      "cites": ["E12", "E8"]
    },
    {
      "text": "The shortage covers products from Baxter Healthcare, Fresenius Kabi USA LLC, Hikma Pharmaceuticals USA Inc., and SteriMax Inc.",
      "cites": ["E8", "E9", "E10", "E11"]
    },
    {
      "text": "No FDA inspection classification or public signal is recorded for the plants supplying our Corvale sites.",
      "cites": ["E7"]
    },
    {
      "text": "Corvale East holds 9 vials of the 50 mg/mL 60 mL presentation at 3.5 vials per day, giving 2.6 days on hand.",
      "cites": ["D1"]
    },
    {
      "text": "Corvale Lakeside holds 19 vials of the same presentation at 0.7 vials per day, giving 26.5 days on hand.",
      "cites": ["D3"]
    },
    {
      "text": "The top-ranked action is to transfer 8 vials of 50 mg/mL 60 mL from Corvale Lakeside to Corvale East, which would leave Lakeside with 15 days and bring East to 5 days.",
      "cites": ["D8"]
    },
    {
      "text": "Alternate concentration options approved by P&T include Hikma's 50 mg/mL (approved 2026-09-15) and Baxter's 1 g/20 mL (approved 2026-04-18), both requiring pharmacist verification.",
      "cites": ["E13", "E14"]
    }
  ]
}
